import{_ as s,a0 as p,w as i,s as r,I as l,x as t,a1 as n,A as o,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在Ubuntu14.10/Mint7上安装Gnome Flashback  经典桌面 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu14.10/Mint7上安装Gnome Flashback  经典桌面 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu14.10/Mint7上安装Gnome Flashback  经典桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu14.10/Mint7上安装Gnome Flashback  经典桌面 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150209 Install the Gnome Flashback classical desktop on Ubuntu 14.10 or Linux Mint 17","title":"在Ubuntu14.10/Mint7上安装Gnome Flashback  经典桌面","tag":"201504","desc":""},"relativePath":"201504/20150209 Install the Gnome Flashback classical desktop on Ubuntu 14.10 or Linux Mint 17.md","filePath":"[post].md"}'),u={name:"201504/20150209 Install the Gnome Flashback classical desktop on Ubuntu 14.10 or Linux Mint 17.md"};function d(k,a,b,c,h,g){const e=p("Link");return i(),r("div",null,[a[16]||(a[16]=l("h1",{id:"在ubuntu14-10-mint7上安装gnome-flashback-经典桌面",tabindex:"-1"},[t("在Ubuntu14.10/Mint7上安装Gnome Flashback 经典桌面 "),l("a",{class:"header-anchor",href:"#在ubuntu14-10-mint7上安装gnome-flashback-经典桌面","aria-label":"Permalink to “在Ubuntu14.10/Mint7上安装Gnome Flashback  经典桌面”"},"​")],-1)),l("p",null,[a[1]||(a[1]=t("如果你不喜欢现在的Unity桌面，",-1)),n(e,{href:"https://wiki.gnome.org/action/show/Projects/GnomeFlashback?action=show&redirect=GnomeFlashback"},{default:o(()=>[...a[0]||(a[0]=[t("Gnome Flashback",-1)])]),_:1}),a[2]||(a[2]=t("桌面环境是一个简单的并且很棒的选择，让你能找回曾经经典的桌面。",-1))]),a[17]||(a[17]=m(`<p>Gnome Flashback基于GTK3并提供与原先gnome桌面视觉上相似的界面。</p><p>Gnome Flashback的另一个改变是采用了源自mint和xface的MATE桌面，但无论mint还是xface都是基于GTK2的。</p><h3 id="安装-gnome-flashback" tabindex="-1">安装 Gnome Flashback <a class="header-anchor" href="#安装-gnome-flashback" aria-label="Permalink to “安装 Gnome Flashback”">​</a></h3><p>在你的ubuntu上安装以下包即可：</p><pre><code>$ sudo apt-get install gnome-session-flashback
</code></pre><p>然后注销返回到登录界面，单击密码输入框右上角的徽标型按钮，即可选择桌面环境。可供选择的有Gnome Flashback (Metacity) 会话模式和Gnome Flashback (Compiz)会话模式。</p><p>Metacity更轻更快，而Compiz则能带给你更棒的桌面效果。下面是我使用gnome flashback桌面的截图。</p><p>桌面采用了elementary OS的壁纸和Plank dock并且移除了底部面板。这些都会在这篇教程中涉及到。</p><p><img src="http://www.binarytides.com/blog/wp-content/uploads/2015/02/ubuntu-gnome-flashback.png" alt="ubuntu gnome flashback"></p><p>在安装好gnome flashback桌面以后也许你对效果还不满意，这样你可能需要执行接下来的一系列操作来对它进行微调。</p><h3 id="_1-安装-gnome-tweak-tool" tabindex="-1">1. 安装 Gnome Tweak Tool <a class="header-anchor" href="#_1-安装-gnome-tweak-tool" aria-label="Permalink to “1. 安装 Gnome Tweak Tool”">​</a></h3><p>Gnome Tweak Tool能够帮助你定制比如字体、主题等，这些在Unity桌面的控制中心是十分困难，几乎不可能完成的任务。</p><pre><code>$ sudo apt-get install gnome-tweak-tool
</code></pre><p>启动按步骤： 应用程序 &gt; 系统工具 &gt; 首选项 &gt; Tweak Tool</p><h3 id="_2-在面板上添加小应用" tabindex="-1">2. 在面板上添加小应用 <a class="header-anchor" href="#_2-在面板上添加小应用" aria-label="Permalink to “2. 在面板上添加小应用”">​</a></h3><p>默认的右键点击面板是没有效果的。你可以尝试在右键点击面板的同时按住键盘上的Alt+Super (win)键，这样就会出现定制面板的相关选项。</p><p>你可以修改或删除面板，并在上面添加些小应用。在这个例子中我们移除了底部面板，并用Plank dock来代替它的位置。</p><p>在顶部面板的中间添加一个显示时间的小应用。通过配置使它显示时间和天气。</p><p>同样的添加一个工作空间切换器到顶部面板，并创建合适个数的工作空间。</p><h3 id="_3-将窗口标题栏的按钮右置" tabindex="-1">3. 将窗口标题栏的按钮右置 <a class="header-anchor" href="#_3-将窗口标题栏的按钮右置" aria-label="Permalink to “3. 将窗口标题栏的按钮右置”">​</a></h3><p>在ubuntu中，最小化、最大化和关闭按钮默认是在标题栏左侧的。需要稍作手脚才能让他们乖乖回到右边去。</p><p>想让窗口的按钮到右边可以使用下面的命令，这是我在askubuntu上找到的。</p><pre><code>$ gsettings set org.gnome.desktop.wm.preferences button-layout &#39;menu:minimize,maximize,close&#39;
</code></pre><h3 id="_4-安装-plank-dock" tabindex="-1">4.安装 Plank dock <a class="header-anchor" href="#_4-安装-plank-dock" aria-label="Permalink to “4.安装 Plank dock”">​</a></h3><p>plank dock位于屏幕底部，用于启动应用和切换打开的窗口。它会在必要的时间隐藏自己，并在需要的时候出现。elementary OS使用的dock就是plank dock。</p><p>运行以下命令安装:</p><pre><code>$ sudo add-apt-repository ppa:ricotz/docky -y 
$ sudo apt-get update 
$ sudo apt-get install plank -y
</code></pre><p>现在启动：应用程序 &gt; 附件 &gt; Plank。若想让它开机自动启动，找到 应用程序 &gt; 系统工具 &gt; 首选项 &gt; 启动应用程序 并将“plank”的命令加到列表中。</p><h3 id="_5-安装-conky-系统监视器" tabindex="-1">5. 安装 Conky 系统监视器 <a class="header-anchor" href="#_5-安装-conky-系统监视器" aria-label="Permalink to “5. 安装 Conky 系统监视器”">​</a></h3><p>Conky非常酷，它用系统的中如CPU和内存使用率的统计值来装饰桌面。它不太占资源，并且绝大部分情况下运行都不会有什么问题。</p><p>运行如下命令安装:</p><pre><code>$ sudo apt-add-repository -y ppa:teejee2008/ppa
$ sudo apt-get update
$ sudo apt-get install conky-manager
</code></pre><p>现在启动：应用程序 &gt; 附件 &gt; Conky Manager ，选择你想在桌面上显示的部件。Conky Manager同样可以配置到启动项中。</p><h3 id="_6-安装ccsm" tabindex="-1">6. 安装CCSM <a class="header-anchor" href="#_6-安装ccsm" aria-label="Permalink to “6. 安装CCSM”">​</a></h3><p>如果你更愿意使用Gnome Flashback (Compiz)，那么CCSM将是你配置桌面特效的得力助手。</p><p>运行以下命令安装:</p><pre><code>$ sudo apt-get install compizconfig-settings-manager
</code></pre><p>启动按步骤： 应用程序 &gt; 系统工具 &gt; 首选项 &gt; CompizConfig Settings Manager.</p><blockquote><p>在虚拟机中经常会发生compiz会话中装饰窗口消失。可以通过启动Compiz设置，并启用&quot;Copy to texture&quot;插件，注销后重新登录即可。</p></blockquote><p>不过值得一提的是Compiz 会话会比Metacity慢。</p><hr>`,41)),l("p",null,[a[4]||(a[4]=t("via: ",-1)),n(e,{href:"http://www.binarytides.com/install-gnome-flashback-ubuntu/"},{default:o(()=>[...a[3]||(a[3]=[t("http://www.binarytides.com/install-gnome-flashback-ubuntu/",-1)])]),_:1})]),l("p",null,[a[8]||(a[8]=t("作者：",-1)),n(e,{href:"https://plus.google.com/117145272367995638274/posts"},{default:o(()=>[...a[5]||(a[5]=[t("Silver Moon",-1)])]),_:1}),a[9]||(a[9]=t(" 译者：",-1)),n(e,{href:"https://github.com/martin2011qi"},{default:o(()=>[...a[6]||(a[6]=[t("martin2011qi",-1)])]),_:1}),a[10]||(a[10]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...a[7]||(a[7]=[t("wxy",-1)])]),_:1})]),l("p",null,[a[13]||(a[13]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[11]||(a[11]=[t("LCTT",-1)])]),_:1}),a[14]||(a[14]=t(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...a[12]||(a[12]=[t("Linux中国",-1)])]),_:1}),a[15]||(a[15]=t(" 荣誉推出",-1))])])}const x=s(u,[["render",d]]);export{T as __pageData,x as default};
